#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: Marquee TV accounts and secrets (build plan card R4).
#
# Every stage is safe to re-run: it finds what exists before creating
# anything. Values go straight from the CLI or your paste into Vercel and
# GitHub Actions; nothing is written to disk.
#
#   scripts/provision/wizard.sh               run every stage in order
#   scripts/provision/wizard.sh --only <name> run one stage (verify.sh names it)
# ──────────────────────────────────────────────────────────────────────────

# shellcheck source=lib.sh source-path=SCRIPTDIR
. "$(dirname "$0")/lib.sh"

STAGES=(clis github vercel supabase google-cloud google-oauth stripe sentry llm email verify)
ONLY=""
if [[ "${1:-}" == "--only" ]]; then
  ONLY="${2:-}"
  [[ " ${STAGES[*]} " == *" $ONLY "* ]] || { echo "stages: ${STAGES[*]}" >&2; exit 2; }
fi

# need CLI... stops the wizard when a CLI it is about to use has no session.
need() {
  local cli
  for cli in "$@"; do
    command -v "$cli" >/dev/null 2>&1 && logged_in "$cli" && continue
    warn "$cli is not installed or not logged in: run scripts/provision/wizard.sh --only clis"
    exit 1
  done
}

# supabase_token asks once per run for a Supabase personal access token. The
# Management API calls below need it; the Supabase CLI's own login can't be
# reused from a script.
SUPABASE_PAT=""
supabase_token() {
  [[ -n "$SUPABASE_PAT" ]] && return
  say "The next step calls the Supabase Management API, which needs an access token."
  open_url "https://supabase.com/dashboard/account/tokens"
  step "Generate new token → name it \"marquee provisioning\" → copy it."
  ask_secret SUPABASE_PAT "Paste the Supabase access token:"
}

# supabase_api METHOD PATH [JSON]: the token goes in through a header file so
# it never shows in the process list.
supabase_api() {
  local method="$1" path="$2" data=()
  [[ -n "${3:-}" ]] && data=(--data-binary "$3")
  curl -fsS -X "$method" "https://api.supabase.com$path" \
    -H @<(printf 'Authorization: Bearer %s\n' "$SUPABASE_PAT") \
    -H 'Content-Type: application/json' ${data[@]+"${data[@]}"}
}

# sentry_api METHOD PATH [JSON], with the token passed the same way.
sentry_api() {
  local method="$1" path="$2" data=()
  [[ -n "${3:-}" ]] && data=(--data-binary "$3")
  curl -fsS -X "$method" "https://sentry.io/api/0$path" \
    -H @<(printf 'Authorization: Bearer %s\n' "$SENTRY_AUTH_TOKEN") \
    -H 'Content-Type: application/json' ${data[@]+"${data[@]}"}
}

# resend_api and cloudflare_api METHOD PATH [JSON], the same way.
resend_api() {
  local method="$1" path="$2" data=()
  [[ -n "${3:-}" ]] && data=(--data-binary "$3")
  curl -fsS -X "$method" "https://api.resend.com$path" \
    -H @<(printf 'Authorization: Bearer %s\n' "$RESEND_KEY") \
    -H 'Content-Type: application/json' ${data[@]+"${data[@]}"}
}
cloudflare_api() {
  local method="$1" path="$2" data=()
  [[ -n "${3:-}" ]] && data=(--data-binary "$3")
  curl -fsS -X "$method" "https://api.cloudflare.com/client/v4$path" \
    -H @<(printf 'Authorization: Bearer %s\n' "$CLOUDFLARE_TOKEN") \
    -H 'Content-Type: application/json' ${data[@]+"${data[@]}"}
}

# ── 1. CLIs ───────────────────────────────────────────────────────────────
stage_clis() {
  stage "Install and log in to the CLIs"
  local cli install login
  for cli in gh vercel supabase gcloud stripe sentry-cli; do
    case "$cli" in
      gh) install="brew install gh"; login="gh auth login" ;;
      vercel) install="npm install -g vercel"; login="vercel login" ;;
      supabase) install="brew install supabase/tap/supabase"; login="supabase login" ;;
      gcloud) install="brew install --cask gcloud-cli"; login="gcloud auth login" ;;
      stripe) install="brew install stripe/stripe-cli/stripe"; login="" ;;
      sentry-cli) install="brew install getsentry/tools/sentry-cli"; login="" ;;
    esac
    if ! command -v "$cli" >/dev/null 2>&1; then
      confirm "$cli is missing. Run \`$install\`?" && $install
    fi
    if [[ -n "$login" ]] && ! logged_in "$cli"; then
      say "$cli: a browser opens; sign in with the account that will own Marquee TV."
      $login
    fi
    if logged_in "$cli"; then printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$cli"; else warn "$cli still has no session"; fi
  done
  note "stripe and sentry-cli take their keys in their own stages, so they need no login."
  pause
}

# ── 2. GitHub Actions environments ────────────────────────────────────────
stage_github() {
  stage "GitHub Actions environments"
  need gh
  local env
  for env in "${ENVIRONMENTS[@]}"; do
    gh api -X PUT "repos/$GITHUB_REPO/environments/$env" >/dev/null
    printf '  %s✓%s environment %s on %s\n' "$GREEN" "$RESET" "$env" "$GITHUB_REPO"
  done
  pause
}

# ── 3. Vercel project ─────────────────────────────────────────────────────
stage_vercel() {
  stage "Vercel project linked to GitHub"
  need vercel
  if vc project inspect "$VERCEL_PROJECT" >/dev/null 2>&1; then
    note "project $VERCEL_PROJECT exists"
  else
    show vc project create "$VERCEL_PROJECT" >/dev/null
    printf '  %s✓%s created project %s\n' "$GREEN" "$RESET" "$VERCEL_PROJECT"
  fi
  # `project create` has no framework option, so set it here; this also fixes an existing project.
  show vc project update "$VERCEL_PROJECT" --framework nextjs --yes >/dev/null
  printf '  %s✓%s %s uses the Next.js preset\n' "$GREEN" "$RESET" "$VERCEL_PROJECT"
  local out
  # The CLI exits 1 with "already connected" when there's nothing to do.
  until out=$(vc git connect "https://github.com/$GITHUB_REPO" --project "$VERCEL_PROJECT" --yes 2>&1) ||
    grep -q 'already connected' <<<"$out"; do
    sed 's/^/    /' <<<"$out"
    warn "Vercel couldn't connect $GITHUB_REPO. If the error above is about access, its GitHub app needs the repo."
    open_url "https://github.com/apps/vercel/installations/new"
    step "Choose your account → Only select repositories → add ${GITHUB_REPO#*/} → Save."
    confirm "Done? Try connecting again" || { SKIPPED+=("Vercel git connect (re-run --only vercel)"); return; }
  done
  printf '  %s✓%s %s deploys from %s\n' "$GREEN" "$RESET" "$VERCEL_PROJECT" "$GITHUB_REPO"
  pause
}

# ── 4. Supabase staging and production ────────────────────────────────────
# supabase_project ENV finds or creates the project behind ENV and sets its
# URL, keys and DATABASE_URL.
supabase_project() {
  local env="$1" name ref orgs org password="" keys pooler status=""
  name=$(supabase_project_name "$env")
  ref=$(supabase_ref "$name")
  if [[ -z "$ref" ]]; then
    orgs=$(show sb orgs list -o json)
    if [[ $(jq length <<<"$orgs") -gt 1 ]]; then
      jq -r '.[] | "    \(.id)  \(.name)"' <<<"$orgs"
      ask org "Organization id for $name:"
    else
      org=$(jq -r '.[0].id' <<<"$orgs")
    fi
    confirm "Create Supabase project $name in $SUPABASE_REGION (org $(jq -r --arg o "$org" '.[] | select(.id == $o) | .name' <<<"$orgs"))?" || { SKIPPED+=("Supabase $name"); return; }
    password=$(openssl rand -hex 24)
    show sb projects create "$name" --org-id "$org" --region "$SUPABASE_REGION" \
      --db-password "$password" -o json >/dev/null
    ref=$(supabase_ref "$name")
    printf '  %s✓%s created %s (%s)\n' "$GREEN" "$RESET" "$name" "$ref"
  fi

  say "waiting for $name to come up…"
  for _ in $(seq 60); do
    status=$(show sb projects list -o json | jq -r --arg r "$ref" '.[] | select(.id == $r) | .status') || true
    [[ "$status" == ACTIVE_HEALTHY ]] && break
    sleep 10
  done
  [[ "$status" == ACTIVE_HEALTHY ]] || { warn "$name is still ${status:-unknown} after 10 minutes; re-run --only supabase"; exit 1; }

  keys=$(show sb projects api-keys --project-ref "$ref" --reveal -o json)
  put NEXT_PUBLIC_SUPABASE_URL "$env" "https://$ref.supabase.co"
  put NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "$env" "$(jq -r '[.[] | select(.type == "publishable")][0].api_key' <<<"$keys")"
  put SUPABASE_SECRET_KEY "$env" "$(jq -r '[.[] | select(.type == "secret")][0].api_key' <<<"$keys")"

  # The password exists only at creation. On a re-run, set DATABASE_URL again
  # only if it's missing somewhere, from a reset password.
  if [[ -z "$password" ]]; then
    [[ -z "$(missing DATABASE_URL | awk -v e="$env" '$3 == e')" ]] && { note "DATABASE_URL already set for $env"; return; }
    warn "DATABASE_URL is missing for $env, and the database password can't be read back."
    open_url "https://supabase.com/dashboard/project/$ref/database/settings"
    step "Database password → Reset database password → Generate a password → copy it → Reset."
    ask_secret password "Paste the new database password:"
  fi
  supabase_token
  # The shared pooler: Vercel and GitHub Actions can't reach the IPv6-only direct host.
  pooler=$(supabase_api GET "/v1/projects/$ref/config/database/pooler" |
    jq -r '[.[] | select(.database_type == "PRIMARY")][0].connection_string')
  put DATABASE_URL "$env" "${pooler/\[YOUR-PASSWORD\]/$password}"
}

stage_supabase() {
  stage "Supabase: staging and production"
  need supabase vercel gh
  local env
  for env in "${ENVIRONMENTS[@]}"; do supabase_project "$env"; done
  pause
}

# ── 5. Google Cloud and the YouTube Data API key ──────────────────────────
stage_google_cloud() {
  stage "Google Cloud: YouTube Data API key"
  need gcloud gh
  local project key
  project=$(gcp_project_id)
  if [[ -z "$project" ]]; then
    project="marquee-tv-$(openssl rand -hex 3)"
    confirm "Create Google Cloud project \"$GCP_PROJECT_NAME\" ($project)?" || { SKIPPED+=("Google Cloud project"); return; }
    show gcloud projects create "$project" --name="$GCP_PROJECT_NAME" --quiet
  fi
  note "project $project"
  show gcloud services enable youtube.googleapis.com apikeys.googleapis.com --project "$project" --quiet

  key=$(show gcloud services api-keys list --project "$project" --filter='displayName="marquee-ingest"' \
    --format='value(name)' | head -n1)
  if [[ -z "$key" ]]; then
    show gcloud services api-keys create --project "$project" --display-name=marquee-ingest \
      --api-target=service=youtube.googleapis.com --quiet >/dev/null
    key=$(show gcloud services api-keys list --project "$project" --filter='displayName="marquee-ingest"' \
      --format='value(name)' | head -n1)
  fi
  put_both YOUTUBE_API_KEY "$(show gcloud services api-keys get-key-string "$key" --format='value(keyString)')"
  pause
}

# ── 6. Google OAuth client for Supabase Auth ──────────────────────────────
stage_google_oauth() {
  stage "Google sign-in: OAuth client for Supabase Auth"
  need gcloud supabase
  local project env ref redirects="" client_id client_secret
  project=$(gcp_project_id)
  [[ -n "$project" ]] || { warn "no Google Cloud project yet: run --only google-cloud first"; exit 1; }
  for env in "${ENVIRONMENTS[@]}"; do
    ref=$(supabase_ref "$(supabase_project_name "$env")")
    [[ -n "$ref" ]] || { warn "no Supabase project for $env yet: run --only supabase first"; exit 1; }
    redirects+="https://$ref.supabase.co/auth/v1/callback "
  done

  say "No CLI creates a Google OAuth client, so this one is by hand."
  open_url "https://console.cloud.google.com/auth/overview?project=$project"
  step "Get started → App name: Marquee TV → User support email: yours → Next."
  step "Audience: External → Next → Contact email: yours → Next → agree → Create."
  step "Branding → Authorized domains → add getmarquee.tv and supabase.co → Save."
  note "Leave the app in Testing until /privacy and /terms are live (card D3); then publish it."
  pause "Press Enter when the consent screen is saved"

  open_url "https://console.cloud.google.com/auth/clients/create?project=$project"
  step "Application type: Web application → Name: Supabase Auth."
  step "Authorized redirect URIs → add each of these:"
  for ref in $redirects; do note "    $ref"; done
  step "Create → copy the Client ID and Client secret from the dialog."
  ask client_id "Paste the Client ID:"
  ask_secret client_secret "Paste the Client secret:"

  supabase_token
  for env in "${ENVIRONMENTS[@]}"; do
    ref=$(supabase_ref "$(supabase_project_name "$env")")
    supabase_api PATCH "/v1/projects/$ref/config/auth" "$(jq -n --arg id "$client_id" --arg s "$client_secret" \
      '{external_google_enabled: true, external_google_client_id: $id, external_google_secret: $s}')" >/dev/null
    printf '  %s✓%s Google sign-in on in Supabase %s\n' "$GREEN" "$RESET" "$(supabase_project_name "$env")"
  done
  pause
}

# ── 7. Stripe test mode: prices and webhooks ──────────────────────────────
# stripe_price LOOKUP_KEY NAME CENTS [recurring interval]: finds the price by
# lookup key or creates it with its product, and prints its id.
stripe_price() {
  local id recurring=()
  [[ -n "${4:-}" ]] && recurring=(-d "recurring[interval]=$4")
  id=$(show stripe prices list --lookup-keys "$1" | jq -r '.data[0].id // empty')
  if [[ -z "$id" ]]; then
    id=$(show stripe prices create --currency usd --unit-amount "$3" \
      -d "lookup_key=$1" -d "product_data[name]=$2" ${recurring[@]+"${recurring[@]}"} | jq -r .id)
  fi
  echo "$id"
}

# stripe_webhook ENV URL: one endpoint per environment. Stripe shows a signing
# secret only when the endpoint is created, so an endpoint whose secret is
# missing from Vercel is replaced.
stripe_webhook() {
  local env="$1" url="$2" existing args=() event
  for event in checkout.session.completed invoice.paid customer.subscription.updated customer.subscription.deleted; do
    args+=(--enabled-events "$event")
  done
  existing=$(show stripe webhook_endpoints list --limit 100 |
    jq -r --arg u "$url" '.data[] | select(.url == $u) | .id')
  if [[ -n "$existing" ]]; then
    [[ -z "$(missing STRIPE_WEBHOOK_SECRET | awk -v e="$env" '$3 == e')" ]] && { note "webhook for $env exists"; return; }
    confirm "The $env webhook exists but its secret isn't in Vercel. Replace the endpoint?" || return
    show stripe webhook_endpoints delete "$existing" --confirm >/dev/null
  fi
  put STRIPE_WEBHOOK_SECRET "$env" "$(show stripe webhook_endpoints create \
    --url "$url" "${args[@]}" | jq -r .secret)"
}

stage_stripe() {
  stage "Stripe test mode: keys, prices, webhooks"
  need stripe vercel
  open_url "https://dashboard.stripe.com/test/apikeys"
  step "Make sure the account switcher shows the Marquee TV account and Test mode is on."
  step "Secret key → Reveal test key → copy it (starts sk_test_)."
  ask_secret STRIPE_SECRET_KEY "Paste the test secret key:"
  [[ "$STRIPE_SECRET_KEY" == sk_test_* ]] || { warn "that isn't a test-mode secret key"; exit 1; }
  put_both STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
  # The CLI reads the key from here, which keeps it out of the process list.
  export STRIPE_API_KEY="$STRIPE_SECRET_KEY"

  put_both STRIPE_PRICE_PASS "$(stripe_price marquee_session_pass "Session pass" 299)"
  put_both STRIPE_PRICE_MONTHLY "$(stripe_price marquee_monthly "Monthly" 499 month)"

  stripe_webhook production "${PRODUCTION_URL:-https://getmarquee.tv}/api/webhooks/stripe"
  say "Preview deploys need one stable URL that Stripe can reach (no Vercel login wall)."
  ask PREVIEW_URL "Preview base URL for the webhook, e.g. https://staging.getmarquee.tv (Enter skips):"
  if [[ -n "$PREVIEW_URL" ]]; then
    stripe_webhook preview "${PREVIEW_URL%/}/api/webhooks/stripe"
  else
    SKIPPED+=("Stripe preview webhook: re-run --only stripe with a stable preview URL")
  fi
  pause
}

# ── 8. Sentry ─────────────────────────────────────────────────────────────
stage_sentry() {
  stage "Sentry: project and DSN"
  need sentry-cli vercel
  local org team dsn
  open_url "https://sentry.io/settings/account/api/auth-tokens/"
  step "Sign up or sign in. If you have no organization yet, create one first."
  step "Create New Token → scopes: org:read, project:read, project:write, project:releases → copy it."
  note "The same token uploads source maps from Vercel builds."
  ask_secret SENTRY_AUTH_TOKEN "Paste the Sentry auth token:"
  SENTRY_AUTH_TOKEN="$SENTRY_AUTH_TOKEN" sentry-cli info >/dev/null || { warn "sentry-cli rejected the token"; exit 1; }

  org=$(sentry_api GET /organizations/ | jq -r '.[0].slug')
  if ! sentry_api GET "/projects/$org/$SENTRY_PROJECT_SLUG/" >/dev/null 2>&1; then
    team=$(sentry_api GET "/organizations/$org/teams/" | jq -r '.[0].slug')
    sentry_api POST "/teams/$org/$team/projects/" "$(jq -n --arg s "$SENTRY_PROJECT_SLUG" \
      '{name: $s, slug: $s, platform: "javascript-nextjs"}')" >/dev/null
    printf '  %s✓%s created Sentry project %s/%s\n' "$GREEN" "$RESET" "$org" "$SENTRY_PROJECT_SLUG"
  fi
  dsn=$(sentry_api GET "/projects/$org/$SENTRY_PROJECT_SLUG/keys/" | jq -r '.[0].dsn.public')

  put_both NEXT_PUBLIC_SENTRY_DSN "$dsn"
  put_both SENTRY_ORG "$org"
  put_both SENTRY_PROJECT "$SENTRY_PROJECT_SLUG"
  put_both SENTRY_AUTH_TOKEN "$SENTRY_AUTH_TOKEN"
  pause
}

# ── 9. LLM provider key ───────────────────────────────────────────────────
stage_llm() {
  stage "LLM provider: API keys"
  need vercel gh
  local preview_key production_key
  note "ADR 0008 (card T0) picks the provider; Anthropic is the default it tests first."
  open_url "https://console.anthropic.com/settings/workspaces"
